gait(){return"\u0645\u062f\u0629 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629. \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0645\u062f\u0629 \u0627\u0644\u0643\u0634\u0651\u0627\u0641 15 \u0623\u0648 30 \u0623\u0648 60 \u064a\u0648\u0645\u064b\u0627."},
